// Middle of the Linked List (Fast & Slow Pointers)
let list = AnimatedLinkedList<Int>()
for val in [10, 20, 30, 40, 50] {
    list.append(val)
}

func findMiddleIndex(_ l: AnimatedLinkedList<Int>) -> Int {
    if l.isEmpty { return -1 }
    var slow = 0
    var fast = 0
    while fast < l.count && fast + 1 < l.count {
        slow += 1
        fast += 2
    }
    return slow
}

